    ('soc-4', 'soc-4@social.example'),
    ('soc-5', 'soc-5@social.example'),
    ('soc-6', 'soc-6@social.example'),
    ('soc-7', 'soc-7@social.example'),
    ('soc-8', 'soc-8@social.example')
  ) AS seed(id, email) ON u.email = seed.email OR u.id = seed.id
  WHERE u.id <> seed.id OR u.email <> seed.email;
  IF clash IS NOT NULL THEN
    RAISE EXCEPTION 'Grooveli seed refused: seed accounts collide with existing accounts: %', clash;
  END IF;
  SELECT string_agg(o.id || ' (existing name ' || o.name || ')', ', ') INTO clash
  FROM "Organization" o
  JOIN (VALUES
    ('kestrel-systems', 'Kestrel Systems'),
    ('amberline-health', 'Amberline Health'),
    ('copperleaf-finance', 'Copperleaf Finance'),
    ('saffron-salt', 'Saffron & Salt Hospitality'),
